insert into public.reading_templates (card_id, category_id, position, orientation, interpretation) values
  ('four-of-cups', 'relationship', 'general', 'upright', 'Kejenuhan atau rasa kurang puas dalam hubungan membuatmu menarik diri. Tanyakan apa yang kurang dan bicarakan jujur.'),
  ('four-of-cups', 'friendship', 'general', 'upright', 'Kamu mungkin mengabaikan ajakan teman karena lesu. Hubungi seseorang yang tepat meski hanya sebentar.'),
  ('four-of-cups', 'career', 'general', 'upright', 'Pekerjaan terasa membosankan hingga kamu melewatkan peluang di depan mata. Cari tantangan kecil untuk menghidupkan semangat.'),
  ('four-of-cups', 'finance', 'general', 'upright', 'Rasa tidak puas membuatmu mengabaikan peluang atau berkah yang ada. Syukuri yang sudah ada sambil mencari yang baru.'),
  ('four-of-cups', 'family', 'general', 'upright', 'Di lingkup keluarga, kartu ini menyorot perenungan serta apatis, tanda adanya ketegangan atau beban yang belum terucap. Mulailah dari mendengarkan, bukan membela diri.'),
  ('four-of-cups', 'self-discovery', 'general', 'upright', 'Kamu butuh waktu merenung, tetapi hati-hati agar tidak terjebak dalam kebosanan. Dengarkan apa yang sebenarnya kurang.'),
  ('four-of-cups', 'personal-growth', 'general', 'upright', 'Di jalur pertumbuhan, perenungan dan apatis terasa menantang. Pecah tujuan menjadi langkah yang cukup kecil untuk dijalani hari ini.'),
  ('four-of-cups', 'life-decisions', 'general', 'upright', 'Dalam menimbang pilihan, kartu ini menyorot perenungan serta apatis sebagai hal yang perlu dipertimbangkan lebih matang sebelum melangkah.'),
  ('four-of-cups', 'relationship', 'general', 'reversed', 'Kamu mulai membuka diri kembali dan melihat sisi baik hubungan. Beri kesempatan yang tadinya kamu abaikan.'),
  ('four-of-cups', 'friendship', 'general', 'reversed', 'Kamu kembali tertarik bersosialisasi. Terima ajakan yang selama ini ditunda.'),
  ('four-of-cups', 'career', 'general', 'reversed', 'Motivasi kerja mulai muncul dan peluang baru terlihat. Ambil langkah kecil.'),
  ('four-of-cups', 'finance', 'general', 'reversed', 'Kamu menyadari peluang finansial yang sempat terlewat. Tinjau dan manfaatkan dengan bijak.'),
  ('four-of-cups', 'family', 'general', 'reversed', 'Untuk urusan keluarga, kartu ini menonjolkan kesadaran baru serta bangkit dari apatis. Ini bisa menjadi saat yang baik untuk menyampaikan apresiasi atau meluruskan kesalahpahaman lama.'),
  ('four-of-cups', 'self-discovery', 'general', 'reversed', 'Kabut apatis mulai terangkat. Gunakan energi barumu untuk hal yang benar-benar bermakna.'),
  ('four-of-cups', 'personal-growth', 'general', 'reversed', 'Untuk pertumbuhan pribadi, kesadaran baru dan bangkit dari apatis menunjukkan momentum yang baik. Pilih satu kebiasaan kecil yang selaras dengan arah ini dan jalani secara konsisten.'),
  ('four-of-cups', 'life-decisions', 'general', 'reversed', 'Untuk keputusan hidup, kesadaran baru dan bangkit dari apatis memberi sinyal yang cukup mendukung. Tetap timbang risikonya, lalu ambil langkah yang bisa kamu pertanggungjawabkan.'),
  ('five-of-cups', 'relationship', 'general', 'upright', 'Penyesalan atau kecewa pada hubungan yang berubah. Akui kesedihannya, sambil melihat apa yang masih bisa dijaga.'),
  ('five-of-cups', 'friendship', 'general', 'upright', 'Kecewa karena perubahan pertemanan atau kehilangan teman. Rasa sedih itu wajar; ingat orang yang masih ada di sisimu.'),
  ('five-of-cups', 'career', 'general', 'upright', 'Kegagalan atau kehilangan peluang membuatmu terpaku. Pelajari yang bisa dipelajari lalu cari jalan lain.'),
  ('five-of-cups', 'finance', 'general', 'upright', 'Kerugian atau kehilangan uang membuatmu murung. Hitung apa yang masih tersisa dan susun langkah pemulihan.'),
